{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2173-05-19 20:15:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I’ll be your doctor during this hospital stay. Can you tell me what brought you in today?"
    },
    {
      "turn_number": 2,
      "time": "2173-05-19 20:16:00",
      "speaker": "Patient",
      "text": "Hi, Doctor. My legs have been swelling more than ever—up to my thighs and even my lower back. I’ve been on ceftriaxone for weeks, but it’s not helping."
    },
    {
      "turn_number": 3,
      "time": "2173-05-19 20:17:00",
      "speaker": "Doctor",
      "text": "I see. You were recently treated for cellulitis and are still on antibiotics. But no fever or redness spreading?"
    },
    {
      "turn_number": 4,
      "time": "2173-05-19 20:18:00",
      "speaker": "Patient",
      "text": "No fever. The redness is better, but the swelling is worse. I can barely walk. I tried Lasix last weekend, but it didn’t help much."
    },
    {
      "turn_number": 5,
      "time": "2173-05-19 20:19:00",
      "speaker": "Doctor",
      "text": "Okay. We’ll check for blood clots and start IV diuretics to help with the swelling. We also need to make sure this isn’t a new infection."
    },
    {
      "turn_number": 6,
      "time": "2173-05-19 20:20:00",
      "speaker": "Patient",
      "text": "Thank you. I’m worried it’s another cellulitis flare."
    },
    {
      "turn_number": 7,
      "time": "2173-05-19 20:21:00",
      "speaker": "Doctor",
      "text": "We checked a leg ultrasound. No signs of a blood clot, though we couldn’t see the calf veins well due to swelling. That’s reassuring."
    },
    {
      "turn_number": 8,
      "time": "2173-05-19 20:22:00",
      "speaker": "Patient",
      "text": "Oh, okay. That’s good to hear."
    },
    {
      "turn_number": 9,
      "time": "2173-05-20 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. We’re starting you on IV furosemide—Lasix—to help reduce the swelling. We’ll give 120 mg daily, maybe twice a day."
    },
    {
      "turn_number": 10,
      "time": "2173-05-20 08:16:00",
      "speaker": "Patient",
      "text": "Will that make me pee a lot?"
    },
    {
      "turn_number": 11,
      "time": "2173-05-20 08:17:00",
      "speaker": "Doctor",
      "text": "Yes, that’s the goal. It helps your body get rid of extra fluid. We’ll monitor your kidney function and potassium."
    },
    {
      "turn_number": 12,
      "time": "2173-05-20 08:18:00",
      "speaker": "Patient",
      "text": "I’ve been on bumetanide at home. Should I go back to that?"
    },
    {
      "turn_number": 13,
      "time": "2173-05-20 08:19:00",
      "speaker": "Doctor",
      "text": "Yes, once we stabilize you, we’ll switch back to your usual bumetanide dose. IV Lasix is stronger for now."
    },
    {
      "turn_number": 14,
      "time": "2173-05-20 15:00:00",
      "speaker": "Doctor",
      "text": "We did a CT of your right thigh because of the painful lump. It shows varicose veins, not a tumor or abscess."
    },
    {
      "turn_number": 15,
      "time": "2173-05-20 15:01:00",
      "speaker": "Patient",
      "text": "Oh, thank goodness. I was scared it was something serious."
    },
    {
      "turn_number": 16,
      "time": "2173-05-20 15:02:00",
      "speaker": "Doctor",
      "text": "Yes, it’s not dangerous. But it can contribute to swelling. We’ll keep managing the fluid buildup."
    },
    {
      "turn_number": 17,
      "time": "2173-05-21 08:30:00",
      "speaker": "Doctor",
      "text": "Your labs show mild inflammation, but no active infection yet. We’ll keep an eye on your white blood cell count."
    },
    {
      "turn_number": 18,
      "time": "2173-05-21 08:31:00",
      "speaker": "Patient",
      "text": "I’ve had a dry cough. Is that related?"
    },
    {
      "turn_number": 19,
      "time": "2173-05-21 08:32:00",
      "speaker": "Doctor",
      "text": "Possibly. Your chest X-ray was clear two days ago, but we’ll repeat it if the cough worsens."
    },
    {
      "turn_number": 20,
      "time": "2173-05-22 09:00:00",
      "speaker": "Doctor",
      "text": "Morning. Your repeat chest X-ray is still clear. Cough might be from allergies or reflux."
    },
    {
      "turn_number": 21,
      "time": "2173-05-22 09:01:00",
      "speaker": "Patient",
      "text": "I hope so. My arms are sore where I get injections."
    },
    {
      "turn_number": 22,
      "time": "2173-05-22 09:02:00",
      "speaker": "Doctor",
      "text": "We did an ultrasound. You have small hematomas from the shots. We’ll use warm compresses and your pain meds."
    },
    {
      "turn_number": 23,
      "time": "2173-05-23 08:45:00",
      "speaker": "Doctor",
      "text": "We need to do an echocardiogram to check your heart function. It might explain the fluid retention."
    },
    {
      "turn_number": 24,
      "time": "2173-05-23 08:46:00",
      "speaker": "Patient",
      "text": "Okay, but I’ve had trouble with contrast before."
    },
    {
      "turn_number": 25,
      "time": "2173-05-23 08:47:00",
      "speaker": "Doctor",
      "text": "We’ll use Lumason to improve the images. We’ll monitor you closely."
    },
    {
      "turn_number": 26,
      "time": "2173-05-23 10:15:00",
      "speaker": "Doctor",
      "text": "I need to tell you something. You had a reaction to Lumason—low blood pressure and trouble breathing."
    },
    {
      "turn_number": 27,
      "time": "2173-05-23 10:16:00",
      "speaker": "Patient",
      "text": "Oh no! I felt dizzy and short of breath. I was scared."
    },
    {
      "turn_number": 28,
      "time": "2173-05-23 10:17:00",
      "speaker": "Doctor",
      "text": "We gave you epinephrine and steroids. You responded well. Lumason is now on your allergy list."
    },
    {
      "turn_number": 29,
      "time": "2173-05-23 10:18:00",
      "speaker": "Patient",
      "text": "Will I need another echo?"
    },
    {
      "turn_number": 30,
      "time": "2173-05-23 10:19:00",
      "speaker": "Doctor",
      "text": "The images were poor, so we couldn’t assess heart pressures. But your heart looked okay. We may not need a repeat."
    },
    {
      "turn_number": 31,
      "time": "2173-05-24 09:00:00",
      "speaker": "Doctor",
      "text": "Your leg swelling is improving with the diuretics. You’ve lost about 4 pounds since admission."
    },
    {
      "turn_number": 32,
      "time": "2173-05-24 09:01:00",
      "speaker": "Patient",
      "text": "I can move a bit easier. But I’m still in pain."
    },
    {
      "turn_number": 33,
      "time": "2173-05-24 09:02:00",
      "speaker": "Doctor",
      "text": "We’re continuing your oxycodone and lidocaine patches. Let us know if pain isn’t controlled."
    },
    {
      "turn_number": 34,
      "time": "2173-05-25 08:50:00",
      "speaker": "Doctor",
      "text": "Your white count is going up, and your cough is worse. We’re repeating the chest X-ray."
    },
    {
      "turn_number": 35,
      "time": "2173-05-25 08:51:00",
      "speaker": "Patient",
      "text": "It’s getting deeper. I’m coughing up a little mucus now."
    },
    {
      "turn_number": 36,
      "time": "2173-05-25 10:30:00",
      "speaker": "Doctor",
      "text": "The new X-ray shows a shadow in your left lung. It looks like pneumonia."
    },
    {
      "turn_number": 37,
      "time": "2173-05-25 10:31:00",
      "speaker": "Patient",
      "text": "Oh no. Is it serious?"
    },
    {
      "turn_number": 38,
      "time": "2173-05-25 10:32:00",
      "speaker": "Doctor",
      "text": "It’s mild. We’re starting oral levofloxacin for two weeks. Your sputum culture only showed normal bacteria."
    },
    {
      "turn_number": 39,
      "time": "2173-05-25 10:33:00",
      "speaker": "Patient",
      "text": "Will that interact with my other meds?"
    },
    {
      "turn_number": 40,
      "time": "2173-05-25 10:34:00",
      "speaker": "Doctor",
      "text": "We’ve checked. It’s safe with your current medications, including warfarin."
    },
    {
      "turn_number": 41,
      "time": "2173-05-26 09:15:00",
      "speaker": "Doctor",
      "text": "Your cough is improving, and your white count is coming down. The antibiotics are working."
    },
    {
      "turn_number": 42,
      "time": "2173-05-26 09:16:00",
      "speaker": "Patient",
      "text": "I feel a bit more energy. My legs still ache, but less swollen."
    },
    {
      "turn_number": 43,
      "time": "2173-05-26 09:17:00",
      "speaker": "Doctor",
      "text": "We’re cutting back the IV Lasix. Tomorrow we’ll stop it and rely on your oral bumetanide."
    },
    {
      "turn_number": 44,
      "time": "2173-05-27 08:40:00",
      "speaker": "Doctor",
      "text": "We’re planning for discharge in a couple of days. Your pneumonia is resolving, and swelling is much better."
    },
    {
      "turn_number": 45,
      "time": "2173-05-27 08:41:00",
      "speaker": "Patient",
      "text": "That’s great. What about my PICC line?"
    },
    {
      "turn_number": 46,
      "time": "2173-05-27 08:42:00",
      "speaker": "Doctor",
      "text": "We discussed it with your primary doctor. Since you have trouble with IV access, we’ll keep it for now."
    },
    {
      "turn_number": 47,
      "time": "2173-05-27 08:43:00",
      "speaker": "Patient",
      "text": "Thank you. I’ve had bad experiences with new lines."
    },
    {
      "turn_number": 48,
      "time": "2173-05-27 08:44:00",
      "speaker": "Doctor",
      "text": "We understand. But if you need it long-term, we’ll talk about a port or tunneled line later."
    },
    {
      "turn_number": 49,
      "time": "2173-05-28 09:00:00",
      "speaker": "Doctor",
      "text": "One more thing—we’re referring you to allergy clinic. With your multiple drug allergies, it’s important to get evaluated."
    },
    {
      "turn_number": 50,
      "time": "2173-05-28 09:01:00",
      "speaker": "Patient",
      "text": "I’ve had so many reactions. I hope they can help me avoid them."
    },
    {
      "turn_number": 51,
      "time": "2173-05-28 09:02:00",
      "speaker": "Doctor",
      "text": "Yes, they’ll help identify safe alternatives and possibly do testing."
    },
    {
      "turn_number": 52,
      "time": "2173-05-29 10:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’ll discharge you tomorrow morning."
    },
    {
      "turn_number": 53,
      "time": "2173-05-29 10:01:00",
      "speaker": "Patient",
      "text": "What do I need to do at home?"
    },
    {
      "turn_number": 54,
      "time": "2173-05-29 10:02:00",
      "speaker": "Doctor",
      "text": "Resume your usual bumetanide. Weigh yourself every morning. Call if you gain more than 2 pounds in a day or 5 in a week."
    },
    {
      "turn_number": 55,
      "time": "2173-05-29 10:03:00",
      "speaker": "Patient",
      "text": "And the antibiotics?"
    },
    {
      "turn_number": 56,
      "time": "2173-05-29 10:04:00",
      "speaker": "Doctor",
      "text": "Finish the levofloxacin. Continue penicillin VK twice daily to prevent cellulitis flares."
    },
    {
      "turn_number": 57,
      "time": "2173-05-29 10:05:00",
      "speaker": "Patient",
      "text": "I will. Any restrictions?"
    },
    {
      "turn_number": 58,
      "time": "2173-05-29 10:06:00",
      "speaker": "Doctor",
      "text": "Keep using your walker. Elevate your legs when sitting. Avoid standing too long."
    },
    {
      "turn_number": 59,
      "time": "2173-05-29 10:07:00",
      "speaker": "Patient",
      "text": "And my other meds?"
    },
    {
      "turn_number": 60,
      "time": "2173-05-29 10:08:00",
      "speaker": "Doctor",
      "text": "Continue all your regular medications—Keppra, Topamax, warfarin, thyroid pill, everything."
    },
    {
      "turn_number": 61,
      "time": "2173-05-29 10:09:00",
      "speaker": "Patient",
      "text": "I have appointments lined up?"
    },
    {
      "turn_number": 62,
      "time": "2173-05-29 10:10:00",
      "speaker": "Doctor",
      "text": "Yes, with your primary doctor, lymphedema clinic, and allergy clinic. We’ll send all the records."
    },
    {
      "turn_number": 63,
      "time": "2173-05-30 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re cleared to go home. Your weight is stable, lungs are clear, and legs are much less swollen."
    },
    {
      "turn_number": 64,
      "time": "2173-05-30 08:01:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I feel so much better."
    },
    {
      "turn_number": 65,
      "time": "2173-05-30 08:02:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Remember: daily weights, finish antibiotics, and call if swelling or breathing worsens."
    },
    {
      "turn_number": 66,
      "time": "2173-05-30 08:03:00",
      "speaker": "Patient",
      "text": "I will. Take care."
    },
    {
      "turn_number": 67,
      "time": "2173-05-30 08:04:00",
      "speaker": "Doctor",
      "text": "You too. The nurse will go over your discharge papers now."
    },
    {
      "turn_number": 68,
      "time": "2173-05-30 08:05:00",
      "speaker": "Patient",
      "text": "Okay, thanks again."
    },
    {
      "turn_number": 69,
      "time": "2173-05-30 08:06:00",
      "speaker": "Doctor",
      "text": "One last thing—your discharge weight is 351 pounds. Keep monitoring it closely."
    },
    {
      "turn_number": 70,
      "time": "2173-05-30 08:07:00",
      "speaker": "Patient",
      "text": "I will. I’ll have the home nurse check it too."
    },
    {
      "turn_number": 71,
      "time": "2173-05-30 08:08:00",
      "speaker": "Doctor",
      "text": "Perfect. Stay safe and take care of yourself."
    },
    {
      "turn_number": 72,
      "time": "2173-05-30 08:09:00",
      "speaker": "Patient",
      "text": "I will. Thank you for everything."
    },
    {
      "turn_number": 73,
      "time": "2173-05-30 08:10:00",
      "speaker": "Doctor",
      "text": "You’re very welcome. Have a good trip home."
    },
    {
      "turn_number": 74,
      "time": "2173-05-30 08:11:00",
      "speaker": "Patient",
      "text": "Thanks, Doctor."
    },
    {
      "turn_number": 75,
      "time": "2173-05-30 08:12:00",
      "speaker": "Doctor",
      "text": "If you have any questions later, don’t hesitate to call."
    },
    {
      "turn_number": 76,
      "time": "2173-05-30 08:13:00",
      "speaker": "Patient",
      "text": "I will. Appreciate it."
    },
    {
      "turn_number": 77,
      "time": "2173-05-30 08:14:00",
      "speaker": "Doctor",
      "text": "Take care and get some rest."
    },
    {
      "turn_number": 78,
      "time": "2173-05-30 08:15:00",
      "speaker": "Patient",
      "text": "I plan to."
    },
    {
      "turn_number": 79,
      "time": "2173-05-30 08:16:00",
      "speaker": "Doctor",
      "text": "We’ll follow up with your PCP. Feel better soon."
    },
    {
      "turn_number": 80,
      "time": "2173-05-30 08:17:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor."
    },
    {
      "turn_number": 81,
      "time": "2173-05-30 08:18:00",
      "speaker": "Doctor",
      "text": "You’re welcome. See you soon."
    },
    {
      "turn_number": 82,
      "time": "2173-05-30 08:19:00",
      "speaker": "Patient",
      "text": "Bye."
    },
    {
      "turn_number": 83,
      "time": "2173-05-30 08:20:00",
      "speaker": "Doctor",
      "text": "Goodbye."
    },
    {
      "turn_number": 84,
      "time": "2173-05-30 08:21:00",
      "speaker": "Patient",
      "text": "Take care."
    },
    {
      "turn_number": 85,
      "time": "2173-05-30 08:22:00",
      "speaker": "Doctor",
      "text": "You too."
    }
  ],
  "summary": {
    "admission_start": "2173-05-19 20:10:00",
    "admission_end": "2173-05-30 13:59:00",
    "summary_paragraph": "A woman with chronic lymphedema, morbid obesity, and a history of recurrent cellulitis was admitted for worsening bilateral leg swelling extending into the thighs and lower back, despite recent treatment with ceftriaxone and outpatient diuretics. Imaging ruled out deep vein thrombosis, and CT of the thigh revealed varicose veins without a mass. She was treated with IV furosemide, leading to improved edema. During the hospitalization, she developed a cough and rising white blood cell count; a repeat chest X-ray showed left lower lobe pneumonia, prompting a course of levofloxacin. She also experienced an anaphylactic reaction to Lumason during an echocardiogram, which was treated promptly and added to her allergy list. Her home diuretic, bumetanide, was resumed, and she was discharged on oral antibiotics, penicillin prophylaxis, and all prior medications. She was referred to allergy and lymphedema clinics for follow-up.",
    "problems": [
      "Lymphedema, not elsewhere classified",
      "Pneumonia, unspecified organism",
      "Anaphylactic reaction due to adverse effect of correct drug or medicament properly administered, initial encounter",
      "Chronic diastolic (congestive) heart failure",
      "Morbid (severe) obesity due to excess calories",
      "Obstructive sleep apnea (adult) (pediatric)",
      "Hypothyroidism, unspecified",
      "Epilepsy, unspecified, not intractable, without status epilepticus",
      "Hyperlipidemia, unspecified",
      "Nicotine dependence, cigarettes, uncomplicated",
      "Fibromyalgia",
      "Gastro-esophageal reflux disease without esophagitis",
      "Other chronic pain",
      "Personal history of malignant neoplasm of other female genital organs",
      "Personal history of pulmonary embolism",
      "Hypertensive heart and chronic kidney disease with heart failure and stage 1 through stage 4 chronic kidney disease, or unspecified chronic kidney disease"
    ]
  }
}
